function newFragment(effect, config, editable) {
  const token = editable ? ++frameToken : undefined;
  const options = {...effect.defaults, ...config.options};
  const items = config.items || effect.items || [];
  const json = v => JSON.stringify(v,null,2).replaceAll('<','\\u003c');
  const ready = editable ? `parent.postMessage({kind:'mk-ready',token:${token},fields:[],elements:[],images:[]},'*');` : '';
  const extra = effect.number >= 33;
  const runtime = extra ? runExtraEffect : runNewEffect;
  const runtimeArg = extra ? !config.catalogId && !editable : (effect.artData||{});
  const catalog = config.catalogId ? `document.addEventListener('click',function(event){if(event.target.closest('[data-live]'))return;event.preventDefault();event.stopImmediatePropagation();parent.postMessage({kind:'mk-open',id:${json(effect.id)}},'*')},true);` : '';
  return `<style>\n${FRAME_FONT}\n:host{display:block;width:100%;font-family:Pretendard,Arial,sans-serif}html,body{margin:0;background:transparent}#mk-effect{width:100%;height:500px;position:relative}\n</style>\n<div id="mk-effect"><div class="nx-root" data-kind="${effect.id}"></div></div>\n<script>\n(function(){\n// Настройки эффекта: текст, цвета, движение и видимость деталей.\nconst SETTINGS = ${json(options)};\n// Элементы: можно добавлять, удалять и менять порядок объектов.\nconst ITEMS = ${json(items)};\n${catalog}\n(${runtime.toString()})(${json(effect.id)},SETTINGS,ITEMS,${json(runtimeArg)});\n${ready}\n})();\n<\/script>`;
}

