  const color = value => typeof value === 'string' && /^#[\da-f]{6}$/i.test(value);
  const number = (value,min,max) => (typeof value === 'number' || typeof value === 'string' && /^-?(?:\d+\.?\d*|\.\d+)$/.test(value)) && Number.isFinite(+value) && +value >= min && +value <= max;
