  const catalog=holder.classList.contains('thumb');
  const scale=catalog ? Math.min(1,width/720) : 1;
  const layout=width+':'+height+':'+scale;
  if(frame.dataset.layout===layout)return;
  frame.dataset.layout=layout;
  frame.style.cssText=`color-scheme:normal;position:absolute;top:0;left:0;border:0;max-width:none;width:${catalog ? Math.max(720,width) : width}px;height:${height}px;transform-origin:top left;transform:scale(${scale})`;
